// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    getHighlights,
    deleteCollection,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "color": "#0ea5e9",
        "description": "",
        "name": "Highlights Page Size"
    }`;

    const collectionsPostResponse = await createCollection(client, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Highlights Page Size");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 5101
        },
        "description": "",
        "name": "Page Size Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/page-size"
    }`;

    const linksPostResponse = await createLink(
        client,
        headers,
        linksPostRequestBody,
        {"collection.id": getResponseValue(collectionsPostResponse, "response.id")}
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Page Size Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/page-size");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "red",
        "endOffset": 17,
        "linkId": 5202,
        "startOffset": 0,
        "text": "Page size passage"
    }`;

    const highlightsPostResponse = await createHighlight(
        client,
        headers,
        highlightsPostRequestBody,
        {"linkId": getResponseValue(linksPostResponse, "response.id")}
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(highlightsPostResponse, "response.color"), 'color').toBe("red");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'text').toBe("Page size passage");
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'linkId').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const highlightsGetResponse = await getHighlights(client, headers, {"take": ["250"]});
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);

    // The PR description promises up to 250 highlights in one page, so take=250 is served, not refused.
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'listed id').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.color"), 'listed color').toBe("red");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.text"), 'listed text').toBe("Page size passage");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.id"), 'listed link id').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights").length, 'a page of 250 holds no more than 250').toBeLessThanOrEqual(250);
    expect(getResponseValue(highlightsGetResponse, "response.nextCursor"), 'the only page has no successor').toBeNull();

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
